// 放行了。统计四个小目录体积（sessions 单独后台跑）
const r = await tools.pwsh({
  command: `
foreach ($d in @("C:/Users/jjq21/.dsh/.dsh-memory", "C:/Users/jjq21/.openviking", "C:/Users/jjq21/.dsh/grill-first", "C:/Users/jjq21/.dsh/storages")) {
  $m = Get-ChildItem $d -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum
  "{0,-15} {1,8:N2} MB  {2,5} files" -f (Split-Path $d -Leaf), ($m.Sum/1MB), $m.Count
}
`,
  description: "统计四个小目录体积"
});
console.log(r.stdout);
